public class ThermostatTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Thermostat t = new Thermostat();
        check("default target is 20.0", 20.0, t.getTarget());

        t.setTarget(25.5);
        check("setTarget(25.5) in range", 25.5, t.getTarget());

        t.setTarget(5.0);
        check("setTarget(5.0) clamps up to 10.0", 10.0, t.getTarget());

        t.setTarget(42.0);
        check("setTarget(42.0) clamps down to 30.0", 30.0, t.getTarget());

        t.setTarget(10.0);
        check("lower boundary 10.0 is allowed", 10.0, t.getTarget());

        t.setTarget(30.0);
        check("upper boundary 30.0 is allowed", 30.0, t.getTarget());

        t.setTarget(-100.0);
        check("very cold request still clamps to 10.0", 10.0, t.getTarget());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

