public class Thermostat {

    private double target;

    public Thermostat() {
        this.target = 20.0;
    }

    public void setTarget(double value) {
        if (value < 10.0) {
            value = 10.0;
        } else if (value > 30.0) {
            value = 30.0;
        }
        this.target = value;
    }

    public double getTarget() {
        return target;
    }
}
